115	static bool sf32lb52_bt_rx_ring_valid(struct circular_buf *rx_ring)
116	{
117	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
118	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
119	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
120	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
121	  long buf_size = rx_ring->buffer_size;
122	
123	  return buf_size == (long)SF32LB52_BT_RING_DATA_SIZE &&
124	         rd_idx <= SF32LB52_BT_RING_DATA_SIZE &&
125	         wr_idx <= SF32LB52_BT_RING_DATA_SIZE;
126	}
