129	{
130	  struct circular_buf *rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
131	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
132	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
133	  long buf_size = rx_ring->buffer_size;
134	
135	  if (!sf32lb52_bt_rx_ring_valid(rx_ring))
136	    {
137	      syslog(LOG_WARNING,
138	             "%s rx ring invalid: buf=%ld expected=%lu rd=%08lx wr=%08lx\n",
139	             tag,
140	             buf_size,
141	             (unsigned long)SF32LB52_BT_RING_DATA_SIZE,
142	             (unsigned long)rd_ptr,
143	             (unsigned long)wr_ptr);
144	      return false;
145	    }
146	
147	  return true;
148	}
