204	static size_t sf32lb52_bt_ring_data_len(uint32_t rd_ptr, uint32_t wr_ptr,
205	                                        uint32_t buffer_size)
206	{
207	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
208	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
209	  uint32_t rd_mirror = CB_GET_PTR_MIRROR(rd_ptr);
210	  uint32_t wr_mirror = CB_GET_PTR_MIRROR(wr_ptr);
211	
212	  if (rd_idx == wr_idx)
213	    {
214	      return rd_mirror == wr_mirror ? 0 : buffer_size;
215	    }
216	
217	  if (wr_idx > rd_idx)
218	    {
219	      return wr_idx - rd_idx;
220	    }
221	
222	  return buffer_size - (rd_idx - wr_idx);
223	}
224	
225	static size_t sf32lb52_bt_ring_space_len(uint32_t rd_ptr, uint32_t wr_ptr,
226	                                         uint32_t buffer_size)
227	{
228	  return buffer_size - sf32lb52_bt_ring_data_len(rd_ptr, wr_ptr,
229	                                                buffer_size);
230	}
231	
232	static uint32_t sf32lb52_bt_ring_advance(uint32_t ptr, size_t len,
233	                                         uint32_t buffer_size)
234	{
235	  uint32_t idx = CB_GET_PTR_IDX(ptr);
236	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
237	
238	  idx += len;
239	  if (idx >= buffer_size)
240	    {
241	      idx -= buffer_size;
242	      mirror = ~mirror;
243	    }
244	
245	  return CB_MAKE_PTR_IDX_MIRROR(idx, mirror);
246	}
247	
248	static size_t sf32lb52_bt_ring_copy(uint8_t *dst,
249	                                    const struct circular_buf *rx_ring,
250	                                    uint32_t rd_ptr,
251	                                    size_t len)
252	{
253	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
254	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
255	  size_t tail;
256	
257	  if (len == 0)
258	    {
259	      return 0;
260	    }
261	
262	  tail = rx_ring->buffer_size - rd_idx;
263	  if (tail >= len)
264	    {
265	      memcpy(dst, &pool[rd_idx], len);
266	      return len;
267	    }
268	
269	  memcpy(dst, &pool[rd_idx], tail);
270	  memcpy(&dst[tail], pool, len - tail);
271	  return len;
272	}
273	
274	static size_t sf32lb52_bt_ring_write(struct circular_buf *tx_ring,
275	                                     const uint8_t *src, size_t len)
276	{
277	  uint8_t *pool = (uint8_t *)(tx_ring + 1);
278	  uint32_t wr_ptr = tx_ring->write_idx_mirror;
279	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
280	  size_t space;
281	  size_t tail;
282	
283	  space = sf32lb52_bt_ring_space_len(tx_ring->read_idx_mirror,
284	                                     wr_ptr,
285	                                     tx_ring->buffer_size);
286	  if (space == 0)
287	    {
288	      return 0;
289	    }
290	
291	  if (len > space)
292	    {
293	      len = space;
294	    }
295	
296	  tail = tx_ring->buffer_size - wr_idx;
297	  if (tail >= len)
298	    {
299	      memcpy(&pool[wr_idx], src, len);
300	      up_clean_dcache((uintptr_t)&pool[wr_idx],
301	                      (uintptr_t)&pool[wr_idx] + len);
302	    }
303	  else
304	    {
305	      memcpy(&pool[wr_idx], src, tail);
306	      memcpy(pool, &src[tail], len - tail);
307	      up_clean_dcache((uintptr_t)&pool[wr_idx],
308	                      (uintptr_t)&pool[wr_idx] + tail);
309	      up_clean_dcache((uintptr_t)pool,
310	                      (uintptr_t)pool + len - tail);
311	    }
312	
313	  tx_ring->write_idx_mirror = sf32lb52_bt_ring_advance(wr_ptr, len,
314	                                                       tx_ring->buffer_size);
315	  up_clean_dcache((uintptr_t)tx_ring,
316	                  (uintptr_t)tx_ring + sizeof(*tx_ring));
317	  __DSB();
318	
319	  return len;
320	}
321	
322	static size_t sf32lb52_bt_tx_pending(struct circular_buf *tx_ring,
323	                                     uint32_t *rd_ptr,
324	                                     uint32_t *wr_ptr)
325	{
326	  uint32_t rd;
327	  uint32_t wr;
328	
329	  up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
330	                       (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
331	                       sizeof(*tx_ring));
332	
333	  rd = tx_ring->read_idx_mirror;
334	  wr = tx_ring->write_idx_mirror;
335	
336	  if (rd_ptr != NULL)
337	    {
338	      *rd_ptr = rd;
339	    }
340	
341	  if (wr_ptr != NULL)
342	    {
343	      *wr_ptr = wr;
344	    }
345	
346	  return sf32lb52_bt_ring_data_len(rd, wr, tx_ring->buffer_size);
347	}
