553	static int32_t sf32lb52_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
554	{
555	  struct sf32lb52_bt_env_s *env = &g_sf32lb52_bt_env;
556	  irqstate_t flags;
557	  bool queue_work;
558	
559	  if (handle != env->ipc_port)
560	    {
561	      return -EINVAL;
562	    }
563	
564	  if (!env->queue_open)
565	    {
566	      struct circular_buf *rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
567	      #if SF32LB52_BT_TRACE
568	            syslog(LOG_INFO, "sf32lb52 rx_ind (pre-open) wr=%08lx rd=%08lx\n",
569	              (unsigned long)rx_ring->write_idx_mirror,
570	              (unsigned long)rx_ring->read_idx_mirror);
571	      #endif
572	      return OK;
573	    }
574	
575	  flags = enter_critical_section();
576	  env->rx_work_pending = true;
577	  queue_work = !env->rx_worker_running && work_available(&env->rx_work);
578	  if (queue_work)
579	    {
580	      env->rx_worker_running = true;
581	    }
582	  leave_critical_section(flags);
583	
584	#if SF32LB52_BT_TRACE
585	  {
586	    struct circular_buf *rx_ring =
587	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
588	
589	    up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
590	                         (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
591	                         sizeof(*rx_ring));
592	
593	    syslog(LOG_INFO,
594	           "sf32lb52 rx_ind: size=%lu local=%08lx rd=%08lx wr=%08lx\n",
595	           (unsigned long)size,
596	           (unsigned long)env->rx_read_idx_mirror,
597	           (unsigned long)rx_ring->read_idx_mirror,
598	           (unsigned long)rx_ring->write_idx_mirror);
599	  }
600	#endif
601	
602	  if (queue_work)
603	    {
604	      int ret;
605	
606	      ret = work_queue(HPWORK, &env->rx_work, sf32lb52_bt_rx_worker,
607	                       env, 0);
608	      if (ret < 0)
609	        {
610	          flags = enter_critical_section();
611	          env->rx_worker_running = false;
612	          leave_critical_section(flags);
613	
614	          syslog(LOG_ERR, "sf32lb52 bt queue rx work failed: %d\n", ret);
615	          return ret;
616	        }
617	    }
618	
619	  return OK;
620	}
