722	int sf32lb52_bt_controller_enable(void)
723	{
724	  int ret;
725	
726	  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_ENABLED)
727	    {
728	      return OK;
729	    }
730	
731	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_INITED)
732	    {
733	      return -EPERM;
734	    }
735	
736	  sf32lb52_bt_prepare_stack_nvds();
737	  HAL_LCPU_ASSERT_INFO_clear();
738	
739	  ret = lcpu_power_on();
740	  if (ret != 0)
741	    {
742	      return -EIO;
743	    }
744	
745	  /* The L2H_MAILBOX (0x40002000) is on the LPSYS APB bus.  Its CxIER
746	   * register is only writable when the LPSYS bus bridge is active.
747	   * Wake the LCPU first so the bus bridge is powered, THEN open the
748	   * IPC queue (which writes CxIER to unmask the mailbox RX interrupt).
749	   * The SDK reference ipc_hw_enable_interrupt2() has the same
750	   * HAL_HPAON_WakeCore() before the UNMASK call.
751	   */
752	
753	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
754	  g_sf32lb52_bt_env.wake_held = true;
755	
756	  usleep(500000);
757	
758	  ret = ipc_queue_open(g_sf32lb52_bt_env.ipc_port);
759	  if (ret < 0)
760	    {
761	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
762	      g_sf32lb52_bt_env.wake_held = false;
763	      return ret;
764	    }
765	
766	  /* Flush H2L TX ring to SRAM immediately after ipc_queue_open so
767	   * LCPU sees the reset indices (read_idx=write_idx=0) before it
768	   * tries to process any stale data from a previous session.
769	   */
770	  up_clean_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
771	                  (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
772	                  SF32LB52_BT_TX_BUF_SIZE);
773	  __DSB();
774	
775	  /* After every lcpu_power_on(), LCPU resets its TX ring write pointer
776	   * (write_idx_mirror) to 0 and writes its own boot responses into the
777	   * ring.  HCPU's read pointer (read_idx_mirror) may still hold the
778	   * non-zero value from the previous session -- dirty in DCache or
779	   * stored in SRAM.  If we do not synchronise them:
780	   *
781	   *   circular_buf_data_len() = wrap(write_idx - read_idx)
782	   *
783	   * returns a large garbage value, and LCPU's fresh boot events
784	   * plus ring garbage all replay as "new" HCI responses.  These
785	   * ghost events are consumed by the host as replies to real commands,
786	   * so HCI_Reset (0x0c01) is never actually executed by the controller,
787	   * and bt_le_adv_start later gets "Command Disallowed" (0x07).
788	   *
789	   * Fix: flush DCache to write back any dirty read_idx and to load
790	   * LCPU's current write_idx from SRAM, then advance read_idx to
791	   * write_idx (discard ALL pending LCPU boot data), then clean the
792	   * DCache so LCPU sees the updated read pointer in SRAM.
793	   */
794	
795	  {
796	    struct circular_buf *rx_ring =
797	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
798	
799	    ret = sf32lb52_bt_wait_rx_ring_ready();
800	    if (ret < 0)
801	      {
802	        syslog(LOG_ERR, "sf32lb52 rx ring not ready: %d\n", ret);
803	        ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
804	        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
805	        g_sf32lb52_bt_env.wake_held = false;
806	        return ret;
807	      }
808	
809	    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
810	    g_sf32lb52_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;
811	
812	    up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
813	                    (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
814	                    sizeof(*rx_ring));
815	    __DSB();
816	  }
817	
818	  {
819	    volatile MAILBOX_CH_TypeDef *l2h = L2H_MAILBOX;
820	    uint32_t nvic_bit = (1UL << (LCPU2HCPU_IRQn & 0x1F));
821	    uint32_t nvic_en  = NVIC->ISER[LCPU2HCPU_IRQn >> 5];
822	
823	    (void)l2h;
824	    (void)nvic_bit;
825	    (void)nvic_en;
826	  }
827	
828	  g_sf32lb52_bt_env.queue_open = true;
829	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_ENABLED;
830	
831	  return OK;
832	}
833	
834	int sf32lb52_bt_controller_disable(void)
835	{
836	  int ret = OK;
837	  int tmpret;
838	  bool queue_open;
839	
840	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED)
841	    {
842	      return -EPERM;
843	    }
844	
845	  queue_open = g_sf32lb52_bt_env.queue_open;
846	  g_sf32lb52_bt_env.queue_open = false;
847	  g_sf32lb52_bt_env.rx_work_pending = false;
848	  g_sf32lb52_bt_env.rx_worker_running = false;
849	  if (!work_available(&g_sf32lb52_bt_env.rx_work))
850	    {
851	      tmpret = work_cancel_sync(HPWORK, &g_sf32lb52_bt_env.rx_work);
852	      if (tmpret < 0 && tmpret != -ENOENT && ret == OK)
853	        {
854	          ret = tmpret;
855	        }
856	    }
857	
858	  if (queue_open)
859	    {
860	      tmpret = ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
861	      if (tmpret < 0 && ret == OK)
862	        {
863	          ret = tmpret;
864	        }
865	    }
866	
867	  if (g_sf32lb52_bt_env.wake_held)
868	    {
869	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
870	      g_sf32lb52_bt_env.wake_held = false;
871	    }
872	
873	  tmpret = lcpu_power_off();
874	  if (tmpret != 0 && ret == OK)
875	    {
876	      ret = -EIO;
877	    }
878	
879	  g_sf32lb52_bt_env.notify_host = NULL;
880	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_INITED;
881	  return ret;
882	}
883	
884	int sf32lb52_host_send_packet(const uint8_t *data, uint16_t len)
885	{
886	  struct circular_buf *tx_ring =
887	      (struct circular_buf *)SF32LB52_BT_TX_BUF_ADDR;
888	  uint32_t start_time;
889	  uint32_t tick_count;
890	  size_t written;
891	  size_t remaining;
892	  size_t offset;
893	  size_t chunk;
894	  size_t chunks;
895	  uint32_t wr_ptr;
896	  int ret;
897	
898	  if (data == NULL || len == 0)
899	    {
900	      return -EINVAL;
901	    }
902	
903	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED ||
904	      !g_sf32lb52_bt_env.queue_open)
905	    {
906	      return -ENODEV;
907	    }
908	
909	  offset = 0;
910	  remaining = len;
911	  start_time = HAL_GetTick();
912	  tick_count = 0;
913	  chunks = 0;
914	  wr_ptr = 0;
915	
916	  ret = sf32lb52_bt_wait_tx_idle(tx_ring);
917	  if (ret < 0)
918	    {
919	      return ret;
920	    }
921	
922	  while (remaining > 0)
923	    {
924	      irqstate_t flags;
925	
926	      chunk = sf32lb52_bt_tx_chunk_len(data, len, offset);
927	
928	      up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
929	                           (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
930	                           sizeof(*tx_ring));
931	
932	      flags = enter_critical_section();
933	      written = sf32lb52_bt_ring_write(tx_ring, data + offset, chunk);
934	      leave_critical_section(flags);
935	
936	      if (written == 0)
937	        {
938	          if (HAL_GetTick() != start_time)
939	            {
940	              tick_count++;
941	              start_time = HAL_GetTick();
942	            }
943	
944	          if (tick_count >= 10)
945	            {
946	              syslog(LOG_ERR,
947	                     "sf32lb52 bt tx timeout: remaining=%lu\n",
948	                     (unsigned long)remaining);
949	              return -ETIMEDOUT;
950	            }
951	
952	          continue;
953	        }
954	
955	      offset += written;
956	      remaining -= written;
957	
958	      __DSB();
959	      wr_ptr = tx_ring->write_idx_mirror;
960	      sf32lb52_bt_trigger_tx();
961	      chunks++;
962	    }
963	
964	#if SF32LB52_BT_TRACE
965	  syslog(LOG_INFO,
966	         "sf32lb52 bt tx publish: total=%u chunks=%lu wr=%08lx first=%02x\n",
967	         len,
968	         (unsigned long)chunks,
969	         (unsigned long)wr_ptr,
970	         data[0]);
971	
972	  sf32lb52_bt_log_tx_state(tx_ring, "queued", wr_ptr);
973	#endif
974	
975	  if (data[0] == SF32LB52_BT_H4_CMD)
976	    {
977	      ret = sf32lb52_bt_wait_tx_idle(tx_ring);
978	      if (ret < 0)
979	        {
980	          return ret;
981	        }
982	    }
983	
984	  return OK;
985	}
