200	static ssize_t sf32lb52_bt_h4_packet_len(const uint8_t *data, size_t len)
201	{
202	  uint16_t payload_len;
203	
204	  if (len < H4_HEADER_SIZE)
205	    {
206	      return 0;
207	    }
208	
209	  switch (data[0])
210	    {
211	      case H4_EVT:
212	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s))
213	          {
214	            return 0;
215	          }
216	
217	        payload_len = data[H4_HEADER_SIZE + 1];
218	        return H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + payload_len;
219	
220	      case H4_ACL:
221	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s))
222	          {
223	            return 0;
224	          }
225	
226	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]);
227	        return H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s) + payload_len;
228	
229	      case H4_ISO:
230	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s))
231	          {
232	            return 0;
233	          }
234	
235	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]) & 0x3fff;
236	        return H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s) + payload_len;
237	
238	      default:
239	        return -EINVAL;
240	    }
241	}
