243	static void sf32lb52_bt_normalize_event(uint8_t *data, size_t len)
244	{
245	  uint16_t opcode;
246	
247	  if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 4 ||
248	      data[0] != H4_EVT)
249	    {
250	      return;
251	    }
252	
253	  if (data[1] == BT_HCI_EVT_CMD_COMPLETE && data[2] >= 4)
254	    {
255	      opcode = sf32lb52_bt_get_le16(&data[4]);
256	      if (opcode == BT_HCI_OP_RESET && data[6] != SF32LB52_HCI_STATUS_SUCCESS)
257	        {
258	          data[6] = SF32LB52_HCI_STATUS_SUCCESS;
259	        }
260	    }
261	  else if (data[1] == BT_HCI_EVT_CMD_STATUS && data[2] >= 4)
262	    {
263	      opcode = sf32lb52_bt_get_le16(&data[5]);
264	      if (opcode == BT_HCI_OP_RESET && data[3] != SF32LB52_HCI_STATUS_SUCCESS)
265	        {
266	          data[3] = SF32LB52_HCI_STATUS_SUCCESS;
267	        }
268	    }
269	}
270	
271	static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
272	                                      uint8_t *data, size_t len)
273	{
274	  enum bt_buf_type_e type;
275	  int ret;
276	
277	  if (len <= H4_HEADER_SIZE)
278	    {
279	      return -EINVAL;
280	    }
281	
282	  switch (data[0])
283	    {
284	      case H4_EVT:
285	        sf32lb52_bt_normalize_event(data, len);
286	        type = BT_EVT;
287	        break;
288	
289	      case H4_ACL:
290	        type = BT_ACL_IN;
291	        break;
292	
293	      case H4_ISO:
294	        type = BT_ISO_IN;
295	        break;
296	
297	      default:
298	        return -EINVAL;
299	    }
300	
301	  ret = bt_netdev_receive(&priv->drv,
302	                          type,
303	                          (void *)&data[H4_HEADER_SIZE],
304	                          len - H4_HEADER_SIZE);
305	  if (ret < 0)
306	    {
307	      wlerr("Failed to receive HCI packet: %d\n", ret);
308	    }
309	
310	  return ret;
311	}
312	
313	static int sf32lb52_bt_synth_cmd_complete(struct sf32lb52_bt_priv_s *priv,
314	                                          uint16_t opcode,
315	                                          const uint8_t *return_params,
316	                                          size_t return_len)
317	{
318	  uint8_t event[H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 3 +
319	                SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
320	  size_t payload_len;
321	
322	  if (return_len > SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN)
323	    {
324	      return -E2BIG;
325	    }
326	
327	  payload_len = 3 + return_len;
328	  event[0] = H4_EVT;
329	  event[1] = BT_HCI_EVT_CMD_COMPLETE;
330	  event[2] = payload_len;
331	  event[3] = 1;
332	  sf32lb52_bt_put_le16(&event[4], opcode);
333	  if (return_len > 0)
334	    {
335	      memcpy(&event[6], return_params, return_len);
336	    }
337	
338	  return sf32lb52_bt_forward_packet(priv, event,
339	                                    H4_HEADER_SIZE +
340	                                    sizeof(struct bt_hci_evt_hdr_s) +
341	                                    payload_len);
342	}
343	
344	static int sf32lb52_bt_synth_status_complete(struct sf32lb52_bt_priv_s *priv,
345	                                             uint16_t opcode)
346	{
347	  const uint8_t status = SF32LB52_HCI_STATUS_SUCCESS;
348	
349	  return sf32lb52_bt_synth_cmd_complete(priv, opcode, &status,
350	                                        sizeof(status));
351	}
352	
353	static bool sf32lb52_bt_emulate_cmd(struct sf32lb52_bt_priv_s *priv,
354	                                    uint16_t opcode, int *ret)
355	{
356	  uint8_t params[SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
357	
358	  switch (opcode)
359	    {
360	      case BT_HCI_OP_READ_SUPPORTED_COMMANDS:
361	        memset(params, 0, sizeof(params));
362	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
363	        params[1 + 27] = 1 << 7;
364	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params,
365	                                              SF32LB52_HCI_READ_COMMANDS_RPLEN);
366	        return true;
367	
368	      case BT_HCI_OP_LE_RAND:
369	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
370	        arc4random_buf(&params[1], SF32LB52_HCI_RAND_RPLEN - 1);
371	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params,
372	                                              SF32LB52_HCI_RAND_RPLEN);
373	        return true;
374	
375	      case BT_HCI_OP_READ_LOCAL_EXT_FEATURES:
376	        memset(params, 0, 11);
377	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
378	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 11);
379	        return true;
380	
381	      case BT_HCI_OP_READ_BUFFER_SIZE:
382	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
383	        sf32lb52_bt_put_le16(&params[1], 0x00fb);
384	        params[3] = 0;
385	        sf32lb52_bt_put_le16(&params[4], 4);
386	        sf32lb52_bt_put_le16(&params[6], 0);
387	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 8);
388	        return true;
389	
390	      case BT_HCI_OP_LE_READ_BUFFER_SIZE:
391	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
392	        sf32lb52_bt_put_le16(&params[1], 0x00fb);
393	        params[3] = 4;
394	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 4);
395	        return true;
396	
397	      case BT_HCI_OP_LE_READ_LOCAL_FEATURES:
398	        memset(params, 0, 9);
399	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
400	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 9);
401	        return true;
402	
403	      case BT_HCI_OP_LE_READ_MAX_DATA_LEN:
404	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
405	        sf32lb52_bt_put_le16(&params[1], 0x00fb);
406	        sf32lb52_bt_put_le16(&params[3], 0x0148);
407	        sf32lb52_bt_put_le16(&params[5], 0x00fb);
408	        sf32lb52_bt_put_le16(&params[7], 0x0148);
409	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 9);
410	        return true;
411	
412	      case BT_HCI_OP_LE_READ_MAX_ADV_DATA_LEN:
413	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
414	        sf32lb52_bt_put_le16(&params[1], 31);
415	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 3);
416	        return true;
417	
418	      case BT_HCI_OP_LE_READ_SUPP_STATES:
419	        memset(params, 0, 9);
420	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 9);
421	        return true;
422	
423	      case BT_HCI_OP_LE_READ_RL_SIZE:
424	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
425	        params[1] = 0;
426	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 2);
427	        return true;
428	
429	      case BT_HCI_OP_LE_WRITE_LE_HOST_SUPP:
430	      case BT_HCI_OP_LE_SET_HOST_FEATURE:
431	      case BT_HCI_OP_LE_SET_EVENT_MASK:
432	      case BT_HCI_OP_LE_WRITE_DEFAULT_DATA_LEN:
433	      case BT_HCI_OP_LE_SET_RPA_TIMEOUT:
434	      case BT_HCI_OP_SET_EVENT_MASK:
435	      case BT_HCI_OP_SET_EVENT_MASK_PAGE_2:
436	      case BT_HCI_OP_WRITE_LOCAL_NAME:
437	      case BT_HCI_OP_WRITE_SCAN_ENABLE:
438	      case BT_HCI_OP_WRITE_PAGE_SCAN_ACTIVITY:
439	      case BT_HCI_OP_WRITE_INQUIRY_SCAN_ACTIVITY:
440	      case BT_HCI_OP_WRITE_PAGE_TIMEOUT:
441	      case BT_HCI_OP_WRITE_CLASS_OF_DEVICE:
442	      case BT_HCI_OP_WRITE_INQUIRY_SCAN_TYPE:
443	      case BT_HCI_OP_WRITE_EXTENDED_INQUIRY_RESPONSE:
444	      case BT_HCI_OP_WRITE_INQUIRY_MODE:
445	      case BT_HCI_OP_WRITE_PAGE_SCAN_TYPE:
446	      case BT_HCI_OP_WRITE_SSP_MODE:
447	      case BT_HCI_OP_WRITE_SC_HOST_SUPP:
448	      case BT_HCI_OP_WRITE_DEFAULT_LINK_POLICY_SETTINGS:
449	      case BT_HCI_OP_HOST_BUFFER_SIZE:
450	      case BT_HCI_OP_SET_CTL_TO_HOST_FLOW:
451	        *ret = sf32lb52_bt_synth_status_complete(priv, opcode);
452	        return true;
453	
454	      default:
455	        return false;
456	    }
457	}
458	
459	static struct sf32lb52_bt_priv_s g_sf32lb52_bt_priv =
460	{
461	  .drv =
462	    {
463	      .head_reserve = H4_HEADER_SIZE,
464	      .open         = sf32lb52_bt_open,
465	      .send         = sf32lb52_bt_send,
466	      .close        = sf32lb52_bt_close,
467	    },
468	};
469	
470	static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
471	{
472	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
473	  ssize_t packet_len;
474	  int ret;
475	
476	  if (data == NULL || len == 0)
477	    {
478	      return -EINVAL;
479	    }
480	
481	  if (priv->drop_rx_until_tx)
482	    {
483	      return OK;
484	    }
485	
486	  if (priv->rxlen + len > sizeof(priv->rxbuf))
487	    {
488	      syslog(LOG_ERR,
489	             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u\n",
490	             (unsigned long)priv->rxlen,
491	             len);
492	      priv->rxlen = 0;
493	    }
494	
495	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
496	  priv->rxlen += len;
497	
498	#if SF32LB52_BT_TRACE
499	  syslog(LOG_INFO,
500	         "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
501	         len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
502	#endif
503	
504	  ret = OK;
505	
506	  while (priv->rxlen > 0)
507	    {
508	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
509	      if (packet_len == 0)
510	        {
511	          break;
512	        }
513	
514	      if (packet_len < 0)
515	        {
516	          syslog(LOG_WARNING,
517	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
518	                 priv->rxbuf[0],
519	                 (unsigned long)priv->rxlen);
520	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
521	          priv->rxlen--;
522	          ret = -EINVAL;
523	          continue;
524	        }
525	
526	      if ((size_t)packet_len > priv->rxlen)
527	        {
528	          break;
529	        }
530	
531	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
532	                   (size_t)packet_len);
533	
534	      priv->rxlen -= (size_t)packet_len;
535	      if (priv->rxlen > 0)
536	        {
537	          memmove(priv->rxbuf,
538	                  &priv->rxbuf[packet_len],
539	                  priv->rxlen);
540	        }
541	    }
542	
543	  return ret;
544	}
545	
546	static int sf32lb52_bt_send(struct bt_driver_s *drv,
547	                            enum bt_buf_type_e type,
548	                            void *data, size_t len)
549	{
550	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
551	  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
552	  uint16_t opcode;
553	  int ret;
554	
555	  switch (type)
556	    {
557	      case BT_CMD:
558	        *hdr = H4_CMD;
559	        break;
560	      case BT_ACL_OUT:
561	        *hdr = H4_ACL;
562	        break;
563	      case BT_ISO_OUT:
564	        *hdr = H4_ISO;
565	        break;
566	      default:
567	        return -EINVAL;
568	    }
569	
570	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
571	    {
572	      opcode = sf32lb52_bt_get_le16(data);
573	      if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
574	        {
575	          return ret < 0 ? ret : len;
576	        }
577	
578	      ret = sf32lb52_bt_ensure_controller_enabled(opcode);
579	      if (ret < 0)
580	        {
581	          return ret;
582	        }
583	    }
584	  else
585	    {
586	      ret = sf32lb52_bt_ensure_controller_enabled(0);
587	      if (ret < 0)
588	        {
589	          return ret;
590	        }
591	    }
592	
593	  priv->drop_rx_until_tx = false;
594	
595	  if (SF32LB52_BT_TRACE && type == BT_ACL_OUT)
596	    {
597	      syslog(LOG_INFO,
598	             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
599	             (unsigned int)type,
600	             (unsigned long)(len + drv->head_reserve),
601	             hdr[0],
602	             len >= 1 ? hdr[1] : 0,
603	             len >= 2 ? hdr[2] : 0,
604	             len >= 3 ? hdr[3] : 0,
605	             len >= 4 ? hdr[4] : 0);
606	    }
607	
608	  ret = sf32lb52_host_send_packet(hdr, len + drv->head_reserve);
609	  if (ret < 0)
610	    {
611	      return ret;
612	    }
613	
614	  return len;
615	}
616	
617	static int sf32lb52_bt_ensure_controller_enabled(uint16_t opcode)
618	{
619	  int ret;
620	
621	  ret = sf32lb52_bt_controller_enable();
622	  if (ret < 0)
623	    {
624	      syslog(LOG_ERR,
625	             "sf32lb52 bth4 controller enable failed before opcode=0x%04x: %d\n",
626	             opcode,
627	             ret);
628	    }
629	
630	  return ret;
631	}
632	
633	static int sf32lb52_bt_open(struct bt_driver_s *drv)
634	{
635	  int ret;
636	
637	  (void)drv;
638	
639	  g_sf32lb52_bt_priv.rxlen = 0;
640	  g_sf32lb52_bt_priv.drop_rx_until_tx = true;
641	
642	  ret = sf32lb52_bt_controller_init();
643	  if (ret < 0)
644	    {
645	      return ret;
646	    }
647	
648	  ret = sf32lb52_hci_register_callback(sf32lb52_bt_recv_cb);
649	  if (ret < 0)
650	    {
651	      return ret;
652	    }
653	
654	  return OK;
655	}
656	
657	static void sf32lb52_bt_close(struct bt_driver_s *drv)
658	{
659	  int ret;
660	
661	  (void)drv;
662	
663	  g_sf32lb52_bt_priv.rxlen = 0;
664	
665	  /* Full deinit (not just disable) so that the next open re-initialises
666	   * the IPC queue from a clean state.  Without deinit, controller_init
667	   * is skipped on re-open (status != IDLE), and LCPU's ring-buffer
668	   * read pointer (reset on power-on) diverges from HCPU's stale write
669	   * pointer, causing all HCI commands to be silently dropped. */
670	  ret = sf32lb52_bt_controller_deinit();
671	  if (ret < 0)
672	    {
673	      wlerr("Failed to deinit HCI controller: %d\n", ret);
674	    }
675	}
676	
677	int sf32lb52_bt_initialize(void)
678	{
679	  int ret;
680	
681	  ret = uart_bth4_register("/dev/ttyHCI0", &g_sf32lb52_bt_priv.drv);
682	  if (ret < 0 && ret != -EEXIST)
683	    {
684	      wlerr("Failed to register /dev/ttyHCI0: %d\n", ret);
685	      return ret;
686	    }
687	
688	  sf32lb52_bt_zblue_init_once();
689	
690	  return OK;
691	}
