#define SF32LB58_HCI_STATUS_SUCCESS          0x00
#define SF32LB58_HCI_READ_COMMANDS_RPLEN     65
#define SF32LB58_HCI_RAND_RPLEN              9
#define SF32LB58_HCI_MAX_CMD_COMPLETE_RPLEN  SF32LB58_HCI_READ_COMMANDS_RPLEN

